const records = parse(rawData, {
  columns: true,
  delimiter: ';',
  skip_empty_lines: true
});

let codeToAppend = '';

records.forEach(row => {
  let severity = 'INFO';
  if (row.severity === 'MAJOR' || row.severity === 'CRITICAL') severity = 'CRITICAL';
  if (row.severity === 'MODERATE' || row.severity === 'WARNING') severity = 'WARNING';

  let drugAId = row.drugAId;
  let drugBId = row.drugBId;
  let drugAName = row.drugAName;
  let drugBName = row.drugBName;

  if (drugAId === 'amoxicillin') {
    drugAId = 'amoxicillin_ped';
  }

  codeToAppend += `  {
    id: ${JSON.stringify(row.id)},
    drugAId: ${JSON.stringify(drugAId)},
    drugBId: ${JSON.stringify(drugBId)},
    drugAName: ${JSON.stringify(drugAName)},
    drugBName: ${JSON.stringify(drugBName)},
    severity: "${severity}",
    mechanism: ${JSON.stringify(row.mechanism)},
    recommendation: ${JSON.stringify(row.recommendation)},
    evidence: ${JSON.stringify(row.evidence)}
  },
`;
});

let interactionsFile = fs.readFileSync('src/interactions.ts', 'utf-8');
const targetStr = `    evidence: "Caduet (Amlodipine and Atorvastatin) Prescribing Information, FDA (2004)."
  }
];`;

if (interactionsFile.includes(targetStr)) {
  const replacement = `    evidence: "Caduet (Amlodipine and Atorvastatin) Prescribing Information, FDA (2004)."
  },
${codeToAppend}];`;
  interactionsFile = interactionsFile.replace(targetStr, replacement);
  fs.writeFileSync('src/interactions.ts', interactionsFile);
  console.log('Successfully appended interactions to src/interactions.ts');
} else {
  console.log('Target string not found');
}
